function walk(container, depth) {
  for (var i = 0; i < container.layers.length; i++) {
    var l = container.layers[i];
    $.writeln(new Array(depth + 1).join("  ") + l.name);
    if (l.typename === "LayerSet") walk(l, depth + 1);
  }
}
