const { app, core } = require("photoshop");
const fs = require("uxp").storage.localFileSystem;

async function exportJpg() {
  const folder = await fs.getFolder();
  const file = await folder.createFile("out.jpg", { overwrite: true });
  await app.activeDocument.saveAs.jpg(file, { quality: 10 }, true);
}
await core.executeAsModal(exportJpg, { commandName: "Export JPEG" });

const { core, action } = require("photoshop");
async function hideActiveLayer() {
  return await action.batchPlay([{
    _obj: "hide",
    _target: [
      { _ref: "layer", _enum: "ordinal" },
      { _ref: "document", _enum: "ordinal" }
    ]
  }], {});
}
await core.executeAsModal(hideActiveLayer, { commandName: "Hide Layer" });

