const { core, imaging, app } = require("photoshop");
await core.executeAsModal(async () => {
  const doc = app.activeDocument;
  const { imageData } = await imaging.getPixels({
    documentID: doc.id, componentSize: 8
  });
  const arr = await imageData.getData();
  console.log("first pixel RGB:", arr[0], arr[1], arr[2]);
  imageData.dispose();
}, { commandName: "Read pixels" });

